33	/// The drafter a speculative engine loads, by checkpoint path.
34	#[derive(Clone, Copy, Debug)]
35	pub(crate) enum DraftModel<'a> {
36	    DFlash(&'a str),
37	    Eagle3(&'a str),
38	}
39	
40	/// One request's verify span: the current dangling token followed by the draft
41	/// candidates (`token_ids[0]` is the confirmed last token, `token_ids[1..]` are
42	/// the `K` drafts). Token-only by construction — the proposer that produced the
43	/// drafts keeps any hidden state to itself.
44	#[derive(Clone)]
45	pub(crate) struct VerifyStepItem {
46	    pub(crate) request_id: RequestId,
47	    pub(crate) token_ids: Vec<u32>,
48	    pub(crate) params: SamplingParams,
49	    pub(crate) stop_policy: StopPolicy,
50	}
51	
52	impl VerifyStepItem {
53	    pub(crate) fn new(
54	        request_id: RequestId,
55	        token_ids: Vec<u32>,
56	        params: SamplingParams,
57	        stop_policy: StopPolicy,
58	    ) -> Self {
59	        Self {
60	            request_id,
61	            token_ids,
62	            params,
63	            stop_policy,
64	        }
65	    }
66	
67	    pub(crate) fn as_slice(&self) -> &[u32] {
68	        &self.token_ids
69	    }
70	}
71	
72	#[derive(Clone, Copy)]
73	pub(crate) struct VerifyPlan<'a> {
74	    pub requests: &'a [VerifyStepItem],
75	    /// Engine step seed for the verify rows' sampler pass (same contract as
76	    /// decode: fresh per step; seeded rows re-mix their own request seed).
77	    pub sample_seed: u64,
78	    /// The load gate turned drafting off for this step: every span is the
79	    /// request's confirmed token alone. Carried separately from the span
80	    /// length because a near-budget request's span is also one token — only
81	    /// this flag says *why* the round has no drafts.
82	    pub gated: bool,
83	}
84	
85	#[derive(Clone, Debug)]
86	pub(crate) struct VerifyRequestResult {
87	    pub request_id: RequestId,
88	    /// Number of matched draft candidates retained after terminal truncation.
89	    pub matched_draft_tokens: usize,
90	    /// Tokens to commit: the accepted draft prefix and the target's posterior
91	    /// token, unless a terminal draft ends the span before the posterior.
92	    /// Always `1..=K + 1` tokens. The worker truncates after the first terminal
93	    /// token before recording DFlash context; the executor checks this at
94	    /// commit, and the scheduler emits the typed stop cause.
95	    pub accepted_tokens: Vec<u32>,
96	}
97	
98	pub(crate) struct VerifyResult {
99	    pub requests: Vec<VerifyRequestResult>,
100	}
101	
102	/// One request's draft request: the proposer continues from `current_token`.
103	/// Deliberately carries no sampling params — the draft rollout is argmax
104	/// regardless of the request's sampler; sampled-verify applies the request's
105	/// params on the verify side only.
106	#[derive(Clone)]
107	pub(crate) struct DraftStepItem {
108	    pub(crate) request_id: RequestId,
109	    pub(crate) current_token: u32,
110	    /// Remaining output budget when the request may be hedged (greedy
111	    /// sampler), `0` otherwise. Carried through the draft seam so the draft
112	    /// lane — which owns the effective branch positions — makes the final
113	    /// eligibility call: a chain only survives the verify-side span clamp
114	    /// when some branch position fits inside `remaining - 1` kept drafts,
115	    /// and a request that cannot show its chain must not burn a hedge slot.
116	    pub(crate) hedge_budget: usize,
117	}
118	
119	impl DraftStepItem {
120	    pub(crate) fn new(request_id: RequestId, current_token: u32, hedge_budget: usize) -> Self {
121	        Self {
122	            request_id,
123	            current_token,
124	            hedge_budget,
125	        }
126	    }
127	}
