145	/// Speculative acceptance — the shared seam every method and sampler reuses.
146	///
147	/// * `proposed` — the `K` candidate tokens from the proposer.
148	/// * `target_tokens` — the target model's *committed* token at each of the
149	///   `K + 1` verify positions: the argmax for a greedy request, the sampled
150	///   token for a non-greedy one. `target_tokens[i]` is the model's pick
151	///   *after* consuming verify input `i`; `target_tokens[0]` follows the last
152	///   confirmed token and `target_tokens[K]` is the model's own continuation
153	///   after the whole candidate run.
154	///
155	/// Returns the longest accepted prefix of `proposed` followed by exactly one
156	/// model token (the correction at the first divergence, or the bonus
157	/// continuation when every candidate is accepted) — always `1..=K + 1` tokens.
158	///
159	/// # Panics
160	/// Panics (debug builds) if `target_argmax.len() != proposed.len() + 1`.
161	#[must_use]
162	fn accept_prefix_match(proposed: &[u32], target_tokens: &[u32]) -> Vec<u32> {
163	    debug_assert_eq!(
164	        target_tokens.len(),
165	        proposed.len() + 1,
166	        "verify must produce one committed token per candidate plus a bonus"
167	    );
168	    let n = num_accepted(proposed, target_tokens);
169	    let mut committed = Vec::with_capacity(n + 1);
170	    committed.extend_from_slice(&proposed[..n]);
171	    // The model's own token at the first divergence (or the bonus continuation
172	    // when the whole run was accepted). `n <= proposed.len() < target_argmax.len()`
173	    // so this index is always valid.
174	    committed.push(target_tokens[n]);
175	    committed
176	}
177	
178	/// Length of the accepted prefix: leading drafts whose token matches the
179	/// target's committed pick.
180	fn num_accepted(proposed: &[u32], target_tokens: &[u32]) -> usize {
181	    let mut i = 0;
182	    while i < proposed.len() && proposed[i] == target_tokens[i] {
183	        i += 1;
184	    }
185	    i
186	}
187	
188	/// Batched acceptance over a verify forward's flattened per-position committed
189	/// tokens. `target_tokens` is the concatenation of each request's `K + 1`
190	/// posterior columns, in `requests` order. Each request applies the shared
191	/// [`accept_prefix_match`] over its own span.
192	pub(crate) fn build_verify_results(
193	    requests: &[VerifyStepItem],
194	    target_tokens: &[u32],
195	) -> Result<Vec<VerifyRequestResult>> {
196	    let mut outputs = Vec::with_capacity(requests.len());
197	    let mut offset = 0usize;
198	    for req in requests {
199	        let span_len = req.token_ids.len();
200	        anyhow::ensure!(
201	            span_len > 0,
202	            "speculative verify request {:?} has an empty verify span",
203	            req.request_id
204	        );
205	        let end = offset + span_len;
206	        anyhow::ensure!(
207	            end <= target_tokens.len(),
208	            "speculative target-token result is shorter than the verify span"
209	        );
210	        let posterior = &target_tokens[offset..end];
211	        // proposed = the K drafts (span minus the leading confirmed token);
212	        // posterior = the K + 1 argmax columns. accept_prefix_match ties them together.
213	        let accepted_tokens = accept_prefix_match(&req.token_ids[1..], posterior);
214	        outputs.push(VerifyRequestResult {
215	            request_id: req.request_id,
216	            matched_draft_tokens: accepted_tokens.len() - 1,
217	            accepted_tokens,
218	        });
219	        offset = end;
220	    }
221	    anyhow::ensure!(
222	        offset == target_tokens.len(),
223	        "unused speculative target-token result columns: used {offset}, total {}",
224	        target_tokens.len()
225	    );
226	    Ok(outputs)
227	}
