1	//! Executor-side speculative-decode orchestration: the optimistic KV
2	//! transaction around a verify forward (schedule → forward → accept/commit or
3	//! roll back) and the thin draft dispatch.
4	//!
5	//! The forward itself runs on the worker lane (see [`super::dflash_lane`]); this
6	//! module owns only the KV bookkeeping the executor thread is responsible for.
7	
8	use anyhow::Result;
9	use pegainfer_frontend::engine::StopPolicy;
10	
11	use super::Qwen3Executor;
12	use super::RequestId;
13	use super::StepCommand;
14	use super::WorkerStepOutcome;
15	use crate::speculative::DraftPlan;
16	use crate::speculative::DraftResult;
17	use crate::speculative::VerifyPlan;
18	use crate::speculative::VerifyRequestResult;
19	use crate::speculative::VerifyResult;
20	
21	/// Remove accepted tokens after the first request-terminal token before the
22	/// speculative KV transaction commits. The scheduler classifies the same
23	/// retained trigger later to produce the typed protocol stop cause.
24	pub(super) fn truncate_after_terminal(
25	    result: &mut VerifyRequestResult,
26	    policy: &StopPolicy,
27	    model_eos: &[u32],
28	) {
29	    let Some(keep) = result.accepted_tokens.iter().position(|&token| {
30	        policy
31	            .classify(token, |id| model_eos.contains(&id))
32	            .is_some()
33	    }) else {
34	        return;
35	    };
36	    let keep = keep + 1;
37	    result.accepted_tokens.truncate(keep);
38	    // A trigger in the accepted draft prefix is itself a matched draft. If the
39	    // trigger is the posterior token, the original count is already `keep - 1`;
40	    // clamping to the retained prefix handles both cases.
41	    result.matched_draft_tokens = result.matched_draft_tokens.min(keep);
42	}
43	
44	impl Qwen3Executor {
45	    pub(super) fn execute_speculative_verify_impl(
46	        &mut self,
47	        plan: VerifyPlan<'_>,
48	    ) -> Result<VerifyResult> {
49	        let verify_round = self.verify_round;
50	        self.verify_round = self.verify_round.wrapping_add(1);
51	        anyhow::ensure!(
52	            self.speculative.is_some(),
53	            "speculative verification requested but no draft model is loaded"
54	        );
55	        for req in plan.requests {
56	            anyhow::ensure!(
57	                !req.as_slice().is_empty(),
58	                "speculative verify request {:?} has an empty verify span",
59	                req.request_id
60	            );
61	            anyhow::ensure!(
62	                self.draft_ready_requests.contains(&req.request_id),
63	                "speculative verification requested before draft state is ready for {:?}",
64	                req.request_id
65	            );
66	            anyhow::ensure!(
67	                self.request_kvs.contains_key(&req.request_id),
68	                "missing RequestKv for {:?}",
69	                req.request_id
70	            );
71	        }
72	
73	        // Reserve KV slots for each request's full K+1 verify span. Roll back
74	        // every prior reservation if any single one fails — all-or-nothing.
75	        let mut scheduled = Vec::with_capacity(plan.requests.len());
76	        for req in plan.requests {
77	            let span_len = req.as_slice().len();
78	            let rkv = self
79	                .request_kvs
80	                .get_mut(&req.request_id)
81	                .expect("RequestKv was validated before speculative scheduling");
82	            if let Err(e) = rkv.schedule_speculative(span_len, self.kv_mgr.pool()) {
83	                self.revert_speculative_schedules(&scheduled);
84	                return Err(anyhow::anyhow!(
85	                    "schedule_speculative failed for {:?}: {e}",
86	                    req.request_id
87	                ));
88	            }
89	            scheduled.push(req.request_id);
90	        }
91	
92	        let kv_views = plan
93	            .requests
94	            .iter()
95	            .map(|req| self.request_kvs[&req.request_id].speculative_view(req.as_slice().len()))
96	            .collect();
97	
98	        let step = StepCommand::SpeculativeVerify {
99	            requests: plan.requests.to_vec(),
100	            kv_views,
101	            sample_seed: plan.sample_seed,
102	            verify_round,
103	            gated: plan.gated,
104	        };
105	        let outcome = match self.run_step(&step) {
106	            Ok(outcome) => outcome,
107	            Err(e) => {
108	                self.revert_speculative_schedules(&scheduled);
109	                return Err(e);
110	            }
111	        };
112	        let result = match outcome {
113	            WorkerStepOutcome::SpeculativeVerify(result) => result,
114	            other => {
115	                self.revert_speculative_schedules(&scheduled);
116	                return Err(anyhow::anyhow!(
117	                    "speculative verify returned unexpected: {}",
118	                    other.kind()
119	                ));
120	            }
121	        };
122	        if result.requests.len() != plan.requests.len() {
123	            self.revert_speculative_schedules(&scheduled);
124	            return Err(anyhow::anyhow!(
125	                "speculative verify returned {} request results for {} requests",
126	                result.requests.len(),
127	                plan.requests.len()
128	            ));
129	        }
130	        for (req, req_result) in plan.requests.iter().zip(&result.requests) {
131	            if req.request_id != req_result.request_id {
132	                self.revert_speculative_schedules(&scheduled);
133	                return Err(anyhow::anyhow!(
134	                    "speculative verify returned request {:?} for {:?}",
135	                    req_result.request_id,
136	                    req.request_id
137	                ));
138	            }
139	            // Workers normalize before recording context. Reject a broken span
140	            // before any KV commit instead of silently repairing it here.
141	            let terminal_position = req_result.accepted_tokens.iter().position(|&token| {
142	                req.stop_policy
143	                    .classify(token, |id| self.metadata.stop_token_ids.contains(&id))
144	                    .is_some()
145	            });
146	            if let Some(position) = terminal_position
147	                && position + 1 != req_result.accepted_tokens.len()
148	            {
149	                self.revert_speculative_schedules(&scheduled);
150	                return Err(anyhow::anyhow!(
151	                    "speculative worker returned an untruncated span for {:?}: \
152	                     terminal token at position {} of {}",
153	                    req_result.request_id,
154	                    position,
155	                    req_result.accepted_tokens.len()
156	                ));
157	            }
158	        }
159	
160	        // Commit the accepted prefix of each request's KV and free the rest.
161	        // On a mid-loop failure, only the not-yet-applied requests roll back
162	        // (applied ones already committed and cannot be reverted).
163	        let mut applied = Vec::with_capacity(result.requests.len());
164	        for req_result in &result.requests {
165	            let rkv = self
166	                .request_kvs
167	                .get_mut(&req_result.request_id)
168	                .expect("request must exist after speculative verify");
169	            if let Err(e) = rkv.apply_speculative(&req_result.accepted_tokens, self.kv_mgr.pool()) {
170	                let unapplied = scheduled
171	                    .iter()
172	                    .copied()
173	                    .filter(|request_id| !applied.contains(request_id))
174	                    .collect::<Vec<_>>();
175	                self.revert_speculative_schedules(&unapplied);
176	                return Err(anyhow::anyhow!(
177	                    "apply_speculative failed for {:?}: {e}",
178	                    req_result.request_id
179	                ));
180	            }
181	            if std::env::var_os("PEGAINFER_TEST_LOG").is_some() {
182	                log::debug!(
183	                    "Qwen3 speculative commit round={} request={} accepted_len={}",
184	                    verify_round,
185	                    req_result.request_id,
186	                    req_result.accepted_tokens.len(),
187	                );
188	            }
189	            applied.push(req_result.request_id);
190	        }
191	        for req_result in &result.requests {
192	            self.save_sealed_blocks(req_result.request_id);
193	        }
194	
195	        if let Some(counters) = self.spec_decode_counters.as_mut() {
196	            for (req, req_result) in plan.requests.iter().zip(&result.requests) {
197	                let num_draft_tokens = req.as_slice().len().saturating_sub(1);
198	                // A load-gated round verifies a one-token span and proposes no
199	                // draft; booking it as one would inflate the published draft
200	                // count and dilute the acceptance rate.
201	                if num_draft_tokens > 0 {
202	                    counters.observe_draft(num_draft_tokens, req_result.matched_draft_tokens);
203	                }
204	            }
205	        }
206	
207	        Ok(result)
208	    }
209	
210	    pub(super) fn execute_speculative_draft_impl(
211	        &mut self,
212	        plan: DraftPlan<'_>,
213	    ) -> Result<DraftResult> {
214	        anyhow::ensure!(
215	            self.speculative.is_some(),
216	            "speculative draft requested but no draft model is loaded"
217	        );
218	        for req in plan.requests {
219	            anyhow::ensure!(
220	                self.draft_ready_requests.contains(&req.request_id),
221	                "speculative draft requested before draft state is ready for {:?}",
222	                req.request_id
223	            );
224	        }
225	        let step = StepCommand::SpeculativeDraft {
226	            requests: plan.requests.to_vec(),
227	        };
228	        match self.run_step(&step)? {
